def find_Min(arr, low, high):
    # Base case: if the array is not rotated at all
    if high < low:
        return arr[0]

    # Base case: if there is only one element left
    if high == low:
        return arr[low]

    # Calculate mid index
    mid = low + (high - low) // 2

    # Check if mid is the minimum element
    if mid < high and arr[mid + 1] < arr[mid]:
        return arr[mid + 1]

    # Check if mid-1 is the minimum element
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid]

    # Decide whether to go to the left half or the right half
    if arr[low] > arr[mid]:
        return find_Min(arr, low, mid - 1)
    else:
        return find_Min(arr, mid + 1, high)

